using System;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace BWVR.Editor {
public static class ReligionChecks {
 static void Require(bool value,string error){if(!value)throw new Exception(error);}
 [MenuItem("BWVR/Verify religion model")]
 public static void VerifyModel(){var r=new ReligionState();float now=0;for(int i=0;i<100;i++){now+=.5f;r.Advance(.5f,now,.2f,false,false);}Require(!r.fanatic&&r.pressure==0,"Individual belief caused collective fanaticism");for(int i=0;i<59;i++){now+=.5f;r.Advance(.5f,now,.75f,false,false);}Require(!r.fanatic,"Fanaticism entered without sustained belief");now+=.5f;r.Advance(.5f,now,.75f,false,false);Require(r.fanatic&&r.episodes==1,"Sustained majority failed to enter fanaticism");for(int i=0;i<18;i++){now+=.5f;r.Advance(.5f,now,1,true,false);}Require(!r.fanatic&&r.recoveries==1&&r.cooldownUntil>now,"Practical diversion did not recover village");for(int i=0;i<100;i++){now+=.5f;r.Advance(.5f,now,1,false,false);}Require(!r.fanatic,"Recovery cooldown failed");var round=JsonUtility.FromJson<ReligionState>(JsonUtility.ToJson(r));Require(round.Valid()&&round.episodes==1&&round.cooldownUntil==r.cooldownUntil,"Religion persistence failed");var old=JsonUtility.FromJson<SliceState>("{\"version\":1,\"seconds\":180,\"water\":52,\"crops\":66,\"trust\":20,\"care\":0.25}");Require(old.Valid()&&old.Religion.Valid(),"Historical season rejected");string before=JsonUtility.ToJson(r);r.Advance(float.NaN,now,1,false,false);Require(before==JsonUtility.ToJson(r),"Invalid time mutated faith model");r.pressure=float.NaN;Require(!r.Valid(),"Invalid pressure accepted");Debug.Log("BWVR_RELIGION_MODEL_PASS");}
 [MenuItem("BWVR/Verify village worship (Play mode)")]
 public static void VerifyRuntime(){Require(EditorApplication.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var flags=BindingFlags.Instance|BindingFlags.NonPublic;var field=typeof(QuestSlice).GetField("state",flags);var original=(SliceState)field.GetValue(slice);var world=slice.GetComponentInChildren<VillageResources>();var god=slice.GetComponentInChildren<CreatureHybrid>();var worship=(VillageWorship)typeof(QuestSlice).GetField("worship",flags).GetValue(slice);var jobs=world.Gatherers.Select(x=>x.GetComponent<VillagerRoutine>()).ToArray();var positions=jobs.Select(x=>x.transform.position).ToArray();var rotations=jobs.Select(x=>x.transform.rotation).ToArray();var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true};god.Interrupt("Religion QA");field.SetValue(slice,test);world.ResetWorld();
  try{for(int i=0;i<jobs.Length;i++){test.Social(i).faith=.95f;test.Social(i).lastFrightAt=-100;test.Social(i).frights=0;test.Social(i).injury=0;}for(int i=0;i<62;i++){test.Hybrid.time+=.5f;worship.Advance(.5f);}Require(test.Religion.fanatic,"Village consensus did not enter fanaticism");var job=jobs[0];Require(worship.Tick(job,.1f)&&worship.Active(job)&&job.Worshipping,"Worship failed to acquire scheduler ownership");Require(!job.GetComponent<VillagerResourceGathering>().Active&&!job.GetComponent<VillagerSocial>().Active&&!job.GetComponent<VillagerExploration>().Active&&!job.GetComponent<VillagerBlockPlay>().Active,"Worship left competing activity owner");var targets=(Vector3[])typeof(VillageWorship).GetField("destinations",flags).GetValue(worship);job.transform.position=targets[0];job.GetComponent<IslandNavigator>().ResetRoute();Physics.SyncTransforms();worship.Tick(job,.1f);Require(test.Social(0).worshipSeconds>0&&job.GetComponentInChildren<HumanoidHands>().praying,"Arrival did not show prayer pose");string before=JsonUtility.ToJson(test);test.paused=true;string paused=JsonUtility.ToJson(test);worship.Advance(.5f);worship.Tick(job,.5f);Require(paused==JsonUtility.ToJson(test),"Pause advanced worship");test.paused=false;job.GetComponent<CarryItem>().held=true;Require(!worship.Tick(job,.1f)&&!worship.Active(job)&&!job.GetComponentInChildren<HumanoidHands>().praying,"Player pickup retained worship ownership");job.GetComponent<CarryItem>().held=false;
   Require(worship.Tick(job,.1f),"Released villager could not resume worship");for(int i=0;i<20;i++){test.Hybrid.time+=.5f;test.Religion.Advance(.5f,test.Hybrid.time,1,true,false);}Require(!test.Religion.fanatic&&!worship.Tick(job,.1f)&&!worship.Active(job)&&!job.Worshipping,"Recovery did not release work scheduler");var copy=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));Require(copy.Valid()&&copy.Religion.episodes==1&&copy.Religion.recoveries==1&&copy.Social(0).worshipSeconds>0,"Worship save/resume invalid");Debug.Log("BWVR_RELIGION_RUNTIME_PASS");
  }finally{foreach(var j in jobs)j.GetComponent<CarryItem>().held=false;field.SetValue(slice,original);worship.ResetWorld();world.ResetWorld();for(int i=0;i<jobs.Length;i++){jobs[i].transform.SetPositionAndRotation(positions[i],rotations[i]);jobs[i].GetComponent<IslandNavigator>().ResetRoute();}god.NewSeason();}
 }
}
}
